clauses = []
vpool = IDPool()
def X(w,p,g): return vpool.id(('X',w,p,g))

for w in range(W):
    for p in range(P):
        lits = [X(w,p,g) for g in range(G)]
        clauses.append(lits)
        for i in range(len(lits)):
            for j in range(i+1,len(lits)):
                clauses.append([-lits[i],-lits[j]])

for w in range(W):
    for g in range(G):
        lits = [X(w,p,g) for p in range(P)]
        cnf = CardEnc.equals(lits=lits, bound=3, vpool=vpool, encoding=EncType.seqcounter)
        for c in cnf.clauses:
            clauses.append(c)

# Pair constraint: for each pair (p,q), at most one week where they share a group
# Define M(w,p,q) aux: p,q together in week w
# Use OR over g of (X(w,p,g) AND X(w,q,g)).
# Actually we can linearize: sum_w sum_g (X(w,p,g) AND X(w,q,g)) <= 1
# Introduce T(w,g,p,q) = AND. Then sum T <= 1.
for p in range(P):
    for q in range(p+1,P):
        Ts = []
        for w in range(W):
            for g in range(G):
                t = vpool.id(('T',w,g,p,q))
                clauses.append([-t, X(w,p,g)])
                clauses.append([-t, X(w,q,g)])
                # don't need reverse direction; we want sum T <= 1, with lower bound irrelevant
                # Actually if they ARE in same group, T can be 0 without violating anything.
                # But sum<=1 still holds. Good.
                Ts.append(t)
        # at most 1 of Ts
        cnf = CardEnc.atmost(lits=Ts, bound=1, vpool=vpool, encoding=EncType.seqcounter)
        for c in cnf.clauses:
            clauses.append(c)

# Hmm but if p,q in same group, we need to COUNT that. Without reverse constraint, T can always be 0
# and at-most-1 is trivially satisfied. That's a bug. Need T >= AND too, OR enforce via:
# Instead, directly: for each w,g, AtMost1 of "p,q both in group g" = at most one pair... 
# Better: the pair constraint "no pair twice" can be: for pair (p,q), sum over w of [same group] <=1
# Need T = AND exactly. Add reverse: t OR -X(w,p,g) OR -X(w,q,g)
for p in range(P):
    for q in range(p+1,P):
        for w in range(W):
            for g in range(G):
                t = vpool.id(('T',w,g,p,q))
                clauses.append([t, -X(w,p,g), -X(w,q,g)])

print("vars:", vpool.top, "clauses:", len(clauses))

