        p = 3*g+i
        fixed.append(X(0,p,g))

solver = Glucose4()
for c in clauses:
    solver.add_clause(c)
for lit in fixed:
    solver.add_clause([lit])

print("solving...")
res = solver.solve()
print(res)
if res:
    model = solver.get_model()
    mset = set(model)
    out = []
    for w in range(W):
        for p in range(P):
            for g in range(G):
                if X(w,p,g) in mset:
                    out.append(g)
                    break
    print(out)
